ALTER TABLE public.challenges ADD COLUMN draft_request_id uuid;
CREATE UNIQUE INDEX challenge_draft_request_unique ON public.challenges(created_by,draft_request_id) WHERE draft_request_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.save_challenge_request(_id uuid,_request uuid,_team uuid,_p jsonb,_activities jsonb,_messages jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL OR _request IS NULL THEN RAISE EXCEPTION 'not_allowed'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||_request::text,0)); cid:=_id; IF cid IS NULL THEN SELECT id INTO cid FROM challenges WHERE created_by=auth.uid() AND draft_request_id=_request; END IF; cid:=public.save_challenge(cid,_team,_p,_activities,_messages); UPDATE challenges SET draft_request_id=coalesce(draft_request_id,_request) WHERE id=cid; RETURN cid; END; $$;
REVOKE ALL ON FUNCTION public.save_challenge_request(uuid,uuid,uuid,jsonb,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_challenge_request(uuid,uuid,uuid,jsonb,jsonb,jsonb) TO authenticated;
CREATE POLICY challenge_activity_privacy ON public.activity AS RESTRICTIVE FOR SELECT TO authenticated USING(type NOT IN ('challenge_streak','challenge_finished','challenge_joined','challenge_cheer') OR (public.can_read_challenge((payload->>'challenge_id')::uuid) AND (type NOT IN ('challenge_streak','challenge_finished') OR actor_id=auth.uid() OR EXISTS(SELECT 1 FROM challenges c WHERE c.id=(payload->>'challenge_id')::uuid AND c.leaderboard_on))));
CREATE OR REPLACE FUNCTION public.challenge_host_enrollments(_c uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE show_names boolean; BEGIN IF NOT public.can_manage_challenge(_c) THEN RAISE EXCEPTION 'not_allowed'; END IF; SELECT leaderboard_on INTO show_names FROM challenges WHERE id=_c; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',CASE WHEN show_names THEN p.full_name ELSE NULL END,'status',m.access_status,'extras',m.extras,'joined_at',m.joined_at)) FROM challenge_members m LEFT JOIN profiles p ON p.id=m.user_id WHERE m.challenge_id=_c),'[]'); END; $$;
CREATE OR REPLACE FUNCTION public.challenge_invite_candidates(_c uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NOT public.can_manage_challenge(_c) THEN RAISE EXCEPTION 'not_allowed'; END IF; SELECT team_id INTO tid FROM challenges WHERE id=_c; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.user_id,'name',p.full_name,'invited',EXISTS(SELECT 1 FROM challenge_invites i WHERE i.challenge_id=_c AND i.user_id=m.user_id AND i.revoked_at IS NULL))) FROM team_members m JOIN profiles p ON p.id=m.user_id WHERE m.team_id=tid AND m.suspended_at IS NULL),'[]'); END; $$;
REVOKE ALL ON FUNCTION public.challenge_invite_candidates(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.challenge_invite_candidates(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_challenge_invite(_c uuid,_user uuid,_on boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_challenge(_c) OR NOT EXISTS(SELECT 1 FROM challenges c JOIN team_members m ON m.team_id=c.team_id WHERE c.id=_c AND m.user_id=_user AND m.suspended_at IS NULL) THEN RAISE EXCEPTION 'not_allowed'; END IF; INSERT INTO challenge_invites(challenge_id,user_id,revoked_at) VALUES(_c,_user,CASE WHEN _on THEN NULL ELSE now() END) ON CONFLICT(challenge_id,user_id) DO UPDATE SET revoked_at=excluded.revoked_at; END; $$;
REVOKE ALL ON FUNCTION public.set_challenge_invite(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_challenge_invite(uuid,uuid,boolean) TO authenticated;